INSERT INTO `articles` (`id`, `user_id`, `title`, `content`, `created_at`) VALUES
(4, 28, 'Test div wrap', 'Ligne simple<br />Deuxieme ligne', 1784815071),
(7, 8, 'zzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzzz', 'aujourd\'hui, nous revenons pour une nouvelle compétition.. et surtout, un nouveau thème !<div><br /></div><div><br /></div><div><br /></div><div>Les règles du concours de l\'Appartement de la Semaine :</div><div><br /></div><div>- Nom de l\'appart : [ADLS] Salle de Cinéma</div><div>- Thème et explications : Durant les deux prochaines semaines, votre mission sera de créer un appartement sur le thème salle de cinéma : popcorn, soda, grand écran, projecteur, prêt pour un petit film !</div><div><br /></div><div><br /></div><div> </div><div><br /></div><div>Comme pour chaque ADLS, des règles sont à respecter :</div><div><br /></div><div>- Nom de l\'appart : [ADLS] Salle de Cinéma</div><div>- 1 à 2 personne(s) par appartement ! </div><div>- L’appartement doit faire minimum 102 cases !</div><div>- Un minimum de 300 mobis / participant est attendu !</div><div>- Le floor et le bug des murs sont autorisés !</div><div><br /></div><div>À la fin de la compétition, les différentes participations seront classées afin de faire ressortir un top de 3 appartements gagnants, ils seront jugés en fonction de l’originalité, l’harmonie, la présence de détails, et les techniques utilisées pour leur construction respective !</div><div><br /></div><div>Pour rappel, les appartements doivent être réalisés sur la période du concours, ils ne doivent pas dater d’un CE ou d’un ADLS antérieur, ni avoir été commencés avant le début. Si deux personnes participent sur le même appartement, il faut le mentionner dans la description de celui-ci !</div><div><br /></div><div><br /></div><div><br /></div><div>Du mobilier cinématographique…</div><div>le retour du MADLS</div><div><br /></div><div>Pour les semaines qui s\'annoncent je vous propose de recréer un mobilier.. Vous allez devoir réaliser un Stand de Pop-corn !</div><div><br /></div><div>Vous pouvez participer seulement pour la partie ADLS, ou seulement pour cette partie, ou bien pour les deux (dans deux appartements séparés). Il suffit de poser vos mobis dans un appartement, sans sol, sans décor et nous visiterons tel quel.</div><div><br /></div><div>Les critères pour le MADLS sont les suivants :</div><div><br /></div><div>-Nom de l’appartement : [MADLS] Stand de Pop-corn (respectez l’orthographe sans quoi les appartements risquent de pas être visités)</div><div>-Nombre de personnes par appartement : 1 personne maximum</div><div><br /></div><div>Pour toutes questions ou requêtes, vous pouvez contacter un architecte officiel sur l’hôtel ou sur discord.</div><div><br /></div><div><br /></div><div>Nous passerons donc dans vos appartement le Samedi 1 Août dans la soirée (à 21h vos appartements doivent être fini et renommé),</div><div><br /></div><div><br /></div><div><br /></div><div><br /></div><div>Les résultats seront postés la semaine suivante.</div><div><br /></div><div>---------------------------------------------</div><div><br /></div><div>Le meilleur pour la fin, alors voici les récompenses :</div><div><br /></div><div>1er gagnant : 15 CityBox’s, un trophée et 20 émeraudes</div><div>2ème gagnant : 10 CityBox’s, un trophée et 15 émeraudes</div><div>3ème gagnant : 5 CityBox’s, un trophée et 10 émeraudes</div><div><br /></div><div>Pour les mobiliers assemblés, l\'unique gagnant repartira avec un trophée, 3 city box\'s et 2 émeraudes.</div><div><br /></div><div>Un badge sera envoyé à toutes les participations sérieuses de l\'ADL &amp; MADLS.</div><div>Une bannière sera également envoyée à tous les gagnants !</div><div><br /></div><div><br /></div><div>Badge :</div><div>par Fais</div><div><br /></div><div><br /></div><div>La bannière actuellement à remporter :</div><div>par Bull.</div>', 1784815429);
