INSERT INTO `website_articles` (`id`, `slug`, `title`, `short_story`, `full_story`, `user_id`, `image`, `can_comment`, `created_at`, `updated_at`, `deleted_at`) VALUES
(1, 'atom-cms-has-been-installed', 'Atom CMS has been installed', 'Welcome to your new hotel, we are super happy that you chose to use Atom CMS!', '<strong>Welcome to your new hotel</strong>!<br><br>First of all thank you for using Atom CMS - it truly means a lot❤️<br><br>We built Atom CMS for you and your users to get the best possible experience when it comes to visiting , and we hope the journey has been a pleasure for you so far.<br><br>We have used modern and industry approved technologies (Laravel & Tailwind CSS) in order to give you the most secure & robust CMS possible.<br><br>Our idea of a good CMS is <strong>accessibility</strong> and just that, is what we have tried to make Atom CMS, so that you can be able to customise it without being a PHP expert or frontend guru. <br/><br/><strong>Some of the built in features</strong><br/>Atom CMS comes packed with tons of features, we will however only mention a few that might help to improve your hotel further!<br/><ul><li>- <a style=\"color: #42b0f5; text-decoration: underline;\" href=\"https://retros.guide/docs/atom-cms/vpn-block\" target=\"_blank\">VPN / IP manager</a> - Allows you to whitelist & blacklist specific IPs or ASNs</li><li>- <a style=\"color: #42b0f5; text-decoration: underline;\" href=\"https://retros.guide/docs/atom-cms/themes\" target=\"_blank\">Theme system</a> - Switch between themes easily or built your own with the simplicity of running a single command!</li><li>- <a style=\"color: #42b0f5; text-decoration: underline;\" href=\"https://retros.guide/docs/atom-cms/recaptcha\" target=\"_blank\">Google ReCaptcha</a> - Keep bots away from your site, by simply enabling Googles recaptcha</li><li>- Built in <a style=\"color: #42b0f5; text-decoration: underline;\" href=\"https://retros.guide/docs/atom-cms/language\" target=\"_blank\">multi language support</a> - Allow your users to browse your site in their preferred language</li></ul><br/><strong>Built in theme system!</strong><br/> Atom CMS has its own theme system, making it an absolute breeze to brew up a new theme or switch themes between the existing ones. If you wish to build your own theme, but is a bit unsure how to start, then head over to the <a style=\"color: #42b0f5; text-decoration: underline;\" href=\"https://retros.guide/docs/atom-cms/themes\" target=\"__blank\">Our documentation site</a>. It gives you a good idea on how to use the theming system and tons of other aspects of running your hotel✨<br><br>With everything being said it is time to wrap up the introduction, but before we do that we want to <strong>wish you the best of luck with your hotel</strong>!', 1, 'website_news_images/default.png', 1, '2025-03-13 17:16:45', '2025-03-13 17:16:45', NULL),
(2, 'pack-aio-arcturus-edition', 'Pack AIO - Arcturus Edition', 'joaowars776', '<p>News test, you can change this in Housekeeping. Thank you for use my Packs, anything, send me a message on Discord: joaowars776</p>', 3, 'website_news_images/01JPGQMQK69KKRFF9JZ1KVWN1Q.gif', 1, '2025-03-17 03:21:46', '2025-03-17 03:21:46', NULL);
INSERT INTO `website_help_center_categories` (`id`, `name`, `content`, `position`, `image_url`, `button_text`, `button_url`, `button_color`, `button_border_color`, `small_box`) VALUES
(1, 'Laravel Way', 'Welcome to the Laravel Hotel, where fun and excitement are always around the corner! 🎉 To ensure that everyone has the best experience possible, we\'ve created The Laravel Way - our special set of rules that keeps our community safe and friendly. 🌈<br/><br/>It\'s important to know that these rules and regulations can change without notice. As a member of our awesome Laravel community, you agree to follow these terms and conditions. 😊 If you don\'t, there may be sanctions applied to your account.<br/><br/>But don\'t worry! If you have any questions or concerns about The Laravel Way, our friendly Hotel Staff are always here to help. 💬 Now, go ahead and click the button below to read The Laravel Way and join us in creating a fantastic environment for all! 🚀', 1, 'safety_tips_1.png', 'Laravel Way', '/help-center/rules', '#eeb425', '#facc15', 0),
(2, 'Ban Appeals', 'If you think you\'ve been unfairly banned from our super cool hotel, no worries - we\'re here to help! 🌟 All you need to do is submit a ticket 🎟️ and let us know what happened.<br/><br/>We\'ll check it out and give you a fair chance to return to the awesome world of Laravel! 🕺💃 So go ahead, share your side of the story, and let\'s get you back in on the fun! 😄', 2, 'safety_tips_5.png', 'Submit a ban appeal', '/help-center/tickets/create', '#eeb425', '#facc15', 0),
(3, 'VPN Unblock', 'We know that sometimes you might need to use a VPN or proxy connection while visiting our fantastic hotel! 🏨 But since we want to keep our community safe and free from toxicity, we block these connections by default. 🛡️<br/><br/>However, we understand that there are exceptions, and we\'re here to help! 🌟 If you find yourself in one of these situations, you can request VPN unblocking:<br/><br/><div style=\'margin-left: 15px;\'><strong>1.</strong> You\'re not using a VPN but still got flagged somehow. 🚩<br/><strong>2.</strong> You\'re at school or university and need a VPN to access Laravel. 🏫<br /><strong>3.</strong> You\'re on public connections that might be flagged as a VPN.</div> 📱<br/><br/>Please note that if using a VPN is optional for you, we usually deny the request. This is just to make sure we maintain a positive and friendly environment for all our users! 😄<br/><br/>To request VPN unblocking, simply submit a ticket with an explanation of your situation, and we\'ll do our best to help you out! Together, let\'s keep the Laravel Hotel experience amazing for everyone! 🎉', 3, 'safety_tips_2.png', 'Submit Unblock request', '/help-center/tickets/create', '#eeb425', '#facc15', 0),
(4, 'Scam Reports', 'Hey Laravel buddies! 🎉 We know that sometimes, unfortunately, users might try to scam others out of their coins, diamonds, or furniture. 😢 But don\'t worry, we\'ve got your back! We don\'t tolerate this kind of behavior, and we\'re here to help you report it. 🌟<br/><br/>Have you been scammed? 😨<br/><br/>If so, we\'re here to assist! Just follow the template below and include it in a ticket under the \'Scam Reports\' option:<br/><br/><div style=\'margin-left: 15px;\'><strong>1.</strong> Scammed by:<br/><strong>2.</strong> Date of Scam:<br/><strong>3.</strong> Items Scammed:<br/><strong>4.</strong> Evidence (if available):</div><br/><br/>Remember, it\'s important to be honest and true to yourself! 🌈 Nobody likes a trickster, and stealing won\'t make you rich - it makes you a criminal. 😔 By reporting scams, we can work together to keep the Laravel Hotel a fun, safe, and amazing place for everyone! 🎊', 4, 'safety_tips_7.png', 'Submit scam report', NULL, '#eeb425', '#facc15', 0),
(5, 'Room Ads', 'Hey there, Laravel friends! 🌟 Did you know that you can make your room even cooler by displaying images in it? 😮 That\'s right! With room background furniture, you can embed images directly into your room on the hotel! 🖼️<br/><br/>However, by default, you won\'t have the furniture access or permission to do this. But no worries, you can apply for it! 🎉 All you need to do is submit a ticket and let us know why you\'d like to have these awesome room ad rights. 📝<br/><br/>Once you\'ve got the permission, you\'ll be able to customize your room and make it truly one-of-a-kind! 🌈 So go ahead and tell us why you need those rights, and let\'s take your room to the next level together! 🚀', 1, NULL, 'Submit a ticket', '/help-center/tickets/create', '#eeb425', '#facc15', 1),
(6, 'Something else?', 'We know that sometimes you might have questions, concerns, or just need a little help that doesn\'t fit into any specific category. No worries, we\'ve got you covered! 🌟<br/><br/>For anything else that you need assistance with, simply select the \'Other\' option when submitting a ticket. 📝<br/><br/>Our friendly and helpful Hotel Staff will be more than happy to get in touch and provide the support you need. 🤗 So go ahead, reach out to us for any reason, big or small, and let\'s make your Laravel experience the best it can be! 🚀', 2, NULL, 'Submit a ticket', '/help-center/tickets/create', '#eeb425', '#facc15', 1);
