(32, 'max_accounts_per_ip', '4', 'The maximum allowed accounts registered per IP address'),
(33, 'google_recaptcha_enabled', '0', 'Toggles whether google recaptcha is enabled or not - Do not enable if turnstile is enabled'),
(34, 'cloudflare_turnstile_enabled', '1', 'Determines whether cloudflare turnstile is enabled or not - Do not enable if google recaptche is enabled'),
(35, 'vpn_block_enabled', '0', 'Toggles whether the VPN blocker is enabled or not'),
(36, 'ipdata_api_key', 'ADD-API-KEY-HERE', 'The API key needed from ipdata.co to block VPNs (Only necessary if vpn block is enabled)'),
(37, 'cms_logo', '/assets/images/generated-logos/habbo_1742147998289.png', 'Default logo for the cms'),
(38, 'cms_header', '/assets/images/kasja_mepage_header.png', 'Default header for the me page'),
(39, 'cms_me_backdrop', '/assets/images/kasja_mepage_image.png', 'Default backdrop header for the me page'),
(40, 'room_thumbnail_path', '/swf/c_images/rooms', 'Path to room thumbnails'),
(41, 'hotel_home_room', '0', 'The homeroom every new users will be assigned to, leave as 0 if you do not wish to assign any home room'),
(42, 'cms_color_mode', 'dark', 'Determines the color mode of the CMS (light = normal, dark = dark mode)'),
(43, 'force_staff_2fa', '0', 'If set to 1 every staff will be forced to apply 2FA before being able to visit any other page'),
(44, 'website_wordfilter_enabled', '0', 'Determines whether the wordfilter on the CMS will be enabled or not'),
(45, 'requires_beta_code', '0', 'Determines whether users need a beta code to register or not (0 for no & 1 for yes)'),
(46, 'disable_registration', '0', 'Determines whether registration is enabled or not (0 for no & 1 for yes)'),
(47, 'give_hc_on_register', '0', 'Determines whether the registered user will receive HC upon registration'),
(48, 'hc_on_register_duration', '315569260', 'Specifies the amount of time a user receives their HC subscription for (The default amount is 10 years)'),
(49, 'max_comment_per_article', '2', 'Specifies the amount of times a user can comment per article'),
(50, 'furniture_icons_path', '/swf/dcr/hof_furni/icons', 'The path used to display furniture icons - eg. on rare values'),
(51, 'nitro_path', '/nitro-react/dist', '/nitro-react/dist or /nitro-cool/dist, or /nitro-xxxxx/dist you put.'),
(52, 'enable_discord_webhook', '0', 'Specify whether Discord webhooks will be sent or not (0 for disabled, 1 for enabled)'),
(53, 'discord_webhook_url', '', 'The URL provided by discord to send a webhook request'),
(54, 'max_guestbook_posts_per_profile', '3', 'The amount of guestbook posts a user can post on each user profile'),
(55, 'tinymce_api_key', 'API-KEY-HERE', 'The API key necessary in order to use TinyMCE');
INSERT INTO `website_shop_articles` (`id`, `website_shop_category_id`, `name`, `info`, `icon_url`, `color`, `costs`, `give_rank`, `credits`, `duckets`, `diamonds`, `badges`, `furniture`, `position`, `is_giftable`, `created_at`, `updated_at`) VALUES
(1, 1, 'Bronze Package', 'Embark on your Habbo adventure with the Bronze Package – your essential starter kit for the virtual world. Start building your dream rooms, customize your avatar, and get access to basic perks that will make your stay more enjoyable.', 'https://i.imgur.com/1VGFYSL.gif', '#c5630f', 500, 2, 5000, 5000, 100, 'VipParties2', NULL, 0, 1, '2025-03-13 17:16:45', '2025-03-13 17:16:45'),
(2, 1, 'Silver Package', 'The Silver Package is designed for Habbos who are ready to take their experience up a notch. Enjoy a substantial boost of in-game currency and exclusive access to items that will set you apart from the crowd.', 'https://i.imgur.com/5NBdR0z.gif', '#dddddd', 1000, 3, 10000, 10000, 300, 'VipParties2_Top100', NULL, 0, 1, '2025-03-13 17:16:46', '2025-03-13 17:16:46'),
(3, 1, 'Gold VIP', 'The Gold VIP package is the epitome of Habbo luxury, reserved for those who crave the ultimate in virtual prestige. Enjoy unparalleled access to exclusive items, premium features, and a status symbol that will make heads turn wherever you go in the Hotel.', 'https://i.imgur.com/NiVvRrs.gif', '#E4A317FF', 1500, 4, 15000, 15000, 500, 'VipParties2_Top10', NULL, 0, 1, '2025-03-13 17:16:46', '2025-03-13 17:16:46');
